'use strict';

const url = require('url');
const { performance } = require('perf_hooks');

const levels = {
    FATAL: 'fatal',
    ERROR: 'error',
    WARN: 'warn',
    INFO: 'info',
    DEBUG: 'debug',
    TRACE: 'trace',
};

const calcLevel = res => {
    if (res.statusCode >= 500) {
        return levels.ERROR;
    }

    if (res.statusCode >= 400) {
        return levels.WARN;
    }

    return levels.INFO;
};

const defaultMessageCreator = ({ req, res }) => {
    const urlObj = url.parse(req.originalUrl || req.url || '');

    urlObj.protocol = req.protocol;
    urlObj.hostname = req.hostname;

    // Будет выводить в лог для каждого запроса:
    // GET /some-url 200 256ms
    req.logger[calcLevel(res)](
        '%s %s %d %sms',
        req.method || 'UNKNOWN',
        url.format(urlObj),
        res.statusCode,
        res.responseTime
    );
};

const createRequestMiddleware = (logger, messageCreator) => {
    const renderMessage = typeof messageCreator === 'function' ? messageCreator : defaultMessageCreator;

    const log = (req, res, startTime, closed = false) => {
        const { err } = res;
        res.responseTime = Math.ceil(performance.now() - startTime);

        renderMessage({ req, res, err }, closed);
    };

    return function yandexLogger(req, res, next) {
        req.logger = logger.child({ req });
        const startTime = performance.now();

        function onResFinished() {
            log(req, res, startTime, false);
            res.removeListener('finish', onResFinished);
            res.removeListener('close', onResClosed);
        }

        function onResClosed() {
            log(req, res, startTime, true);
            res.removeListener('close', onResClosed);
            res.removeListener('finish', onResFinished);
        }

        res.on('finish', onResFinished);
        res.on('close', onResClosed);

        next();
    };
};

module.exports = createRequestMiddleware;
